def duration_contract(cfg=None):
    cfg = cfg or {}
    return {"target_min_seconds": cfg.get("target_min_seconds", cfg.get("candidate_preferred_min_seconds", 30)),
            "target_max_seconds": cfg.get("target_max_seconds", cfg.get("candidate_preferred_max_seconds", 90)),
            "hard_min_seconds": cfg.get("hard_min_seconds", cfg.get("candidate_min_seconds", 8)),
            "hard_max_seconds": cfg.get("hard_max_seconds", cfg.get("candidate_hard_max_seconds", 180)),
            "allow_story_exception": cfg.get("allow_story_exception", True)}


_STORY_COMPONENT_KEYS = ("setup", "development", "payoff")


def _story_component_ids(story, key):
    """Read a real arc component or a legacy duration-proof list of source IDs.

    A duration exception is saved as ``{setup: [IDs], ...}`` by assess_duration.
    A regular story arc uses ``{setup: {segment_ids: [IDs]}, ...}`` instead.
    Both encode the *same observed segment evidence*. Reject all other shapes;
    never synthesize a missing component, ID, or timestamp.
    """
    if not isinstance(story, dict):
        return []
    value = story.get(key)
    if isinstance(value, dict):
        value = value.get("segment_ids")
    if not isinstance(value, (list, tuple)) or not value:
        return []
    if not all(isinstance(item, str) and item.strip() for item in value):
        return []
    if len(set(value)) != len(value):
        return []
    return list(value)


def _complete_story(story, segment_ids):
    if not isinstance(story, dict) or story.get("kind") not in (None, "complete_story"):
        return False
    if story.get("kind") is None and story.get("completeness") != "supported_setup_development_payoff":
        return False
    if not isinstance(segment_ids, (list, tuple)) or not segment_ids:
        return False
    # Validate against the selected contiguous source sequence, not arbitrary
    # semantic IDs. Unknown components or overlapping/reversed arcs cannot earn
    # an exception just because the clip happens to be long.
    source_indices = {segment_id: index for index, segment_id in enumerate(segment_ids)
                      if isinstance(segment_id, str)}
    indices = []
    for key in _STORY_COMPONENT_KEYS:
        component = _story_component_ids(story, key)
        if not component or any(segment_id not in source_indices for segment_id in component):
            return False
        indices.append([source_indices[segment_id] for segment_id in component])
    return max(indices[0]) < min(indices[1]) and max(indices[1]) < min(indices[2])


def assess_duration(start, end, cfg=None, story=None, segment_ids=None):
    contract = duration_contract(cfg)
    duration = end - start
    hard = contract["hard_min_seconds"] <= duration <= contract["hard_max_seconds"]
    target = contract["target_min_seconds"] <= duration <= contract["target_max_seconds"]
    exception = bool(hard and duration > contract["target_max_seconds"] and contract["allow_story_exception"] and
                     _complete_story(story, segment_ids or []))
    # Public duration-proof contract is a mapping of source-ID lists. The
    # ranking stage must be able to consume exactly this representation.
    proof = {key: _story_component_ids(story, key) for key in _STORY_COMPONENT_KEYS} if exception else None
    return {"duration_contract": contract, "duration_exception": exception,
            "duration_exception_reason": "grounded_complete_story_requires_contiguous_setup_and_payoff" if exception else None,
            "duration_exception_evidence": proof,
            "duration_in_target_range": target, "duration_within_hard_range": hard,
            "duration_default_eligible": target or exception,
            "duration_suitability_score": 1.0 if target else .75 if exception else .35 if hard else 0.0,
            "duration_requires_review": not target,
            "duration_soft_max_exceeded": duration > contract["target_max_seconds"]}


def opening_quality(segment, previous=None):
    text = (segment.get("text") or "").strip()
    reasons = []
    if not text:
        reasons.append("missing_text")
    if re.match(r"^(ele|ela|eles|elas|isso|aquilo|esse|essa|mas|porque|entao|ai|e)\b", fold_text(text)):
        reasons.append("missing_antecedent_or_continuation")
    if re.match(r"^(bom[,.]|assim[,.]|quer dizer|tipo assim|tudo bem|tudo bacana|tudo certo)\b", fold_text(text)):
        reasons.append("generic_preamble")
    if previous and previous.get("speaker") == segment.get("speaker") and segment["start"] - previous["end"] < 1 and not (previous.get("text") or "").rstrip().endswith((".", "?", "!")):
        reasons.append("mid_sentence")
    if segment.get("timestamp_anomaly_count") or segment.get("timestamp_suspect"):
        reasons.append("suspect_timestamp")
    return {"clean": not reasons, "reasons": reasons, "method": "grounded_sentence_and_context_boundary"}


def ending_quality(segment):
    text = (segment.get("text") or "").rstrip()
    complete = text.endswith((".", "?", "!")) and not text.endswith(("...", "\u2026"))
    if re.search(r"\b(?:e|mas|porque|que|entao)[.!?]*$", fold_text(text)):
        complete = False
    return {"clean": complete, "reasons": [] if complete else ["incomplete_sentence_or_handoff"],
            "method": "observed_sentence_ending_not_semantic_payoff_probability"}


def _discourse_boundary_review(moment, segments, first, last, cfg, qa_pairs, topic):
    """Validate a proposal against literal context, rather than editorial scores."""
    original = {"start": moment['start'], "end": moment['end']}
    proposed = {"start": segments[first]['start'], "end": segments[last]['end']}
    risks, evidence = [], []
    if topic and (proposed['start'] < topic['start'] or proposed['end'] > topic['end']):
        risks.append('topic_boundary_crossed')
